"""Tracked-tree hygiene: no generated bytecode in the repository.

Why a test rather than a convention, in the idiom of
`tests/test_project_independence.py`: the rule was already there and still failed.
`.gitignore` has carried `__pycache__/` and `*.pyc` since before this file existed
(its lines 17-18), yet `evidence/usb-descriptor-remediation-v2/__pycache__/
mutation_harness_v2.cpython-311.pyc` — 13,725 bytes of compiled Python — reached
`main` in commit `80fc8615283173fd820d26c5779ad0cb94047736` of PR #35. The ignore
rule was defeated by one flag: the staging command used `git add -f <directory>`,
and `--force` means "add this even though it is ignored". An evidence package that
is staged with `-f` because it contains dated notes will sweep up whatever the test
run left beside them.

The cost was not disk space, it was the property the package exists to provide: every
file under `evidence/` is supposed to have an identity that a reader can re-derive.
A `.pyc` cannot be re-derived byte-for-byte — its header carries the source mtime, so
`py_compile` on the same source produces a different file (measured: identical code
section, different header) — so a manifest that recorded it would be recording an
artifact nobody can reproduce, and a manifest that *didn't* record it, as
`HASHES-PR-TIP.txt` did, leaves the tree holding one path no record explains.

These cases keep that from recurring. They assert the ignore rules exist *and* that
the tracked tree obeys them, because either half alone is satisfiable by accident: a
`.gitignore` nobody enforces, or a clean tree that regresses the next time someone
forces an add.

Status of the assertion itself: it inspects `git ls-files`, so outside a Git
repository there is nothing to check. That is reported as a skip with a reason rather
than a pass, so an export (a `git archive` tarball, a CI checkout without `.git`)
cannot read as a green hygiene result.
"""

from __future__ import annotations

import subprocess
import unittest
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent

#: Extensions that are compiled output, never source. `.pyo` is dead upstream but a
#: stale one on disk is exactly the kind of thing this guard exists to catch.
GENERATED_SUFFIXES = (".pyc", ".pyo")
GENERATED_DIR = "__pycache__"


def in_git_repository() -> bool:
    return subprocess.run(["git", "rev-parse", "--git-dir"], cwd=REPO,
                          capture_output=True).returncode == 0


def tracked_files() -> list[str]:
    """Every file git tracks, repository-relative.

    `ls-files` without `-o`: the question is what the repository *carries*, not what
    happens to sit in the working directory. Untracked bytecode is normal and none of
    this test's business.
    """
    out = subprocess.run(["git", "ls-files", "-z"], cwd=REPO,
                         capture_output=True, check=True).stdout
    return [name.decode() for name in out.split(b"\0") if name]


def is_generated_artifact(path: str) -> bool:
    """The predicate the guard uses, factored out so it can be tested directly."""
    parts = path.split("/")
    return path.endswith(GENERATED_SUFFIXES) or GENERATED_DIR in parts


@unittest.skipUnless(in_git_repository(),
                     "no Git index to inspect: `git archive` exports and stripped "
                     "checkouts have nothing for this guard to read, and a skip is "
                     "reported while an unverified pass would not be")
class TrackedBytecodeTest(unittest.TestCase):
    def test_no_generated_bytecode_is_tracked(self):
        offenders = sorted(p for p in tracked_files() if is_generated_artifact(p))
        self.assertEqual(
            offenders, [],
            "these tracked paths are Python bytecode output; they are regenerated on "
            f"import and cannot be re-hashed reliably: {offenders}. They get in the way "
            "described in this file's docstring — a forced `git add` of a directory "
            "whose ignore rules were being bypassed for other reasons.")

    def test_ignore_rules_for_bytecode_are_present(self):
        gitignore = REPO / ".gitignore"
        self.assertTrue(gitignore.is_file(),
                        ".gitignore is missing, so nothing prevents a re-occurrence")
        patterns = {line.strip() for line in
                    gitignore.read_text(encoding="utf-8").splitlines()
                    if line.strip() and not line.startswith("#")}
        for needed in (f"{GENERATED_DIR}/", "*.pyc"):
            self.assertIn(needed, patterns,
                          f"`.gitignore` must carry {needed!r}: a test that fails after "
                          "the fact is a worse outcome than an ignore rule that prevents it")

    def test_the_predicate_is_not_vacuous(self):
        # The failure mode this repository keeps being reviewed for is a check that
        # passes because it never looked at anything. So: pin that the inventory is
        # real, and pin that the predicate fires on the shapes it claims to catch.
        files = tracked_files()
        self.assertGreater(len(files), 100,
                           "the tracked inventory is implausibly short; `git ls-files` "
                           "did not run against a real checkout")
        self.assertTrue(any(p.endswith(".py") for p in files),
                        "no tracked Python source at all — wrong tree?")
        for should_catch in ("__pycache__/x.pyc", "tools/__pycache__/a.cpython-311.pyc",
                             "evidence/pkg/__pycache__/m.cpython-311.pyc", "x.pyc", "x.pyo"):
            self.assertTrue(is_generated_artifact(should_catch), should_catch)
        for should_miss in ("evidence/pkg/HASHES.txt", "tools/pc5ctl.py",
                            "docs/engineering/USB-IDENTITY-BOUNDARY-DESIGN-v1.md",
                            "src/pycache/notbytecode.py"):
            self.assertFalse(is_generated_artifact(should_miss), should_miss)


if __name__ == "__main__":
    unittest.main(verbosity=2)
